-- Feed product_volumes -> tab Product_Volumes, base year 2026. Generated by scripts/it-handover.mjs; do not edit.
-- Column 1 is ROW_KEY (unique; drop it from the data file). The other columns are in sheet order.
-- Product_Volumes: planned finished units per product x flow. Year and month columns come from the SERIES template.
-- PM has one row per product, flow and month: Y is its year, U its units, M its month ('YYYY-MM') and Q its units rounded to 2 decimals.
-- Year cells are rounded after summing. M and Q are unqualified to keep the 24 month lines (current and next year) short (PRODUCT_CATALOG has no such columns).
WITH PM AS (
  SELECT
    PRODUCT_ID,
    INITCAP(PRODUCT_FLOW_TYPE) AS FLOW,
    YEAR(MONTH_START) AS Y,
    TO_CHAR(MONTH_START, 'YYYY-MM') AS M,
    MAX(PRODUCT_DISPLAY_NAME) AS PRODUCT_DISPLAY_NAME,
    MAX(PROGRAM_NAME) AS PROGRAM_NAME,
    MAX(CUSTOMER_NAME) AS CUSTOMER_NAME,
    MAX(EMS_NAME) AS EMS_NAME,
    MAX(PLANNED_PRODUCT_UNITS) AS U,
    MAX(PLANNED_PRODUCT_UNITS)::NUMBER(38,2) AS Q
  FROM MECL_PLATFORM.ANALYTICS.COMPONENT_DEMAND_FORECAST
  GROUP BY PRODUCT_ID, INITCAP(PRODUCT_FLOW_TYPE), MONTH_START
)
SELECT
  PM.PRODUCT_ID::VARCHAR || '|' || PM.FLOW AS ROW_KEY,
  PM.PRODUCT_ID AS PRODUCT_ID,
  MAX(PM.PRODUCT_DISPLAY_NAME) AS PRODUCT_DISPLAY_NAME,
  MAX(C.PROJECT_NAME) AS PROJECT,
  MAX(PM.PROGRAM_NAME) AS PROGRAM,
  MAX(PM.CUSTOMER_NAME) AS CUSTOMER,
  MAX(PM.EMS_NAME) AS EMS,
  PM.FLOW AS FLOW
  ,SUM(IFF(PM.Y=2025,PM.U,0))::NUMBER(38,2) AS UNITS_2025
,SUM(IFF(M='2026-01',Q,0)) AS M_2026_01
,SUM(IFF(M='2026-02',Q,0)) AS M_2026_02
,SUM(IFF(M='2026-03',Q,0)) AS M_2026_03
,SUM(IFF(M='2026-04',Q,0)) AS M_2026_04
,SUM(IFF(M='2026-05',Q,0)) AS M_2026_05
,SUM(IFF(M='2026-06',Q,0)) AS M_2026_06
,SUM(IFF(M='2026-07',Q,0)) AS M_2026_07
,SUM(IFF(M='2026-08',Q,0)) AS M_2026_08
,SUM(IFF(M='2026-09',Q,0)) AS M_2026_09
,SUM(IFF(M='2026-10',Q,0)) AS M_2026_10
,SUM(IFF(M='2026-11',Q,0)) AS M_2026_11
,SUM(IFF(M='2026-12',Q,0)) AS M_2026_12
,SUM(IFF(PM.Y=2026,PM.U,0))::NUMBER(38,2) AS UNITS_2026
,SUM(IFF(M='2027-01',Q,0)) AS M_2027_01
,SUM(IFF(M='2027-02',Q,0)) AS M_2027_02
,SUM(IFF(M='2027-03',Q,0)) AS M_2027_03
,SUM(IFF(M='2027-04',Q,0)) AS M_2027_04
,SUM(IFF(M='2027-05',Q,0)) AS M_2027_05
,SUM(IFF(M='2027-06',Q,0)) AS M_2027_06
,SUM(IFF(M='2027-07',Q,0)) AS M_2027_07
,SUM(IFF(M='2027-08',Q,0)) AS M_2027_08
,SUM(IFF(M='2027-09',Q,0)) AS M_2027_09
,SUM(IFF(M='2027-10',Q,0)) AS M_2027_10
,SUM(IFF(M='2027-11',Q,0)) AS M_2027_11
,SUM(IFF(M='2027-12',Q,0)) AS M_2027_12
,SUM(IFF(PM.Y=2027,PM.U,0))::NUMBER(38,2) AS UNITS_2027
,SUM(IFF(PM.Y=2028,PM.U,0))::NUMBER(38,2) AS UNITS_2028
,SUM(IFF(PM.Y=2029,PM.U,0))::NUMBER(38,2) AS UNITS_2029
,SUM(IFF(PM.Y=2030,PM.U,0))::NUMBER(38,2) AS UNITS_2030
,SUM(IFF(PM.Y=2031,PM.U,0))::NUMBER(38,2) AS UNITS_2031
,SUM(IFF(PM.Y=2032,PM.U,0))::NUMBER(38,2) AS UNITS_2032
,SUM(IFF(PM.Y=2033,PM.U,0))::NUMBER(38,2) AS UNITS_2033
,SUM(IFF(PM.Y=2034,PM.U,0))::NUMBER(38,2) AS UNITS_2034
,SUM(IFF(PM.Y=2035,PM.U,0))::NUMBER(38,2) AS UNITS_2035
,SUM(IFF(PM.Y=2036,PM.U,0))::NUMBER(38,2) AS UNITS_2036
FROM PM
LEFT JOIN MECL_PLATFORM.ANALYTICS.PRODUCT_CATALOG C ON C.PRODUCT_ID = PM.PRODUCT_ID
GROUP BY PM.PRODUCT_ID, PM.FLOW
ORDER BY ROW_KEY;
